using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical details the business layers must not touch directly.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net", "System.IO", "System.Text.Json", "System.Data",
        "System.Diagnostics.Process", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_Application_or_Infrastructure() =>
        AssertNoDependency(Domain, [ApplicationNs, InfrastructureNs]);

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoDependency(Application, [InfrastructureNs]);

    [Fact]
    public void Domain_does_not_use_technical_namespaces() =>
        AssertNoDependency(Domain, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_namespaces() =>
        AssertNoDependency(Application, TechnicalNamespaces);

    [Fact]
    public void Infrastructure_is_the_layer_holding_technical_details() =>
        Assert.NotEmpty(Types.InAssembly(Infrastructure).That().ResideInNamespace(InfrastructureNs).GetTypes());

    private static void AssertNoDependency(Assembly assembly, string[] forbidden)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        var offenders = string.Join(", ", result.FailingTypeNames ?? []);
        Assert.True(result.IsSuccessful, $"Forbidden dependency on [{string.Join(", ", forbidden)}] in: {offenders}");
    }
}
